insert into public.companions (id,name_ar,name_en,slug,bio_ar,bio_en,title_ar,category,order_num,published,metadata) values ('754137d7-f07b-5306-be6e-bf0390eee285','علي بن أبي طالب','Ali ibn Abi Talib','ali-ibn-abi-talib','ابن عم النبي ﷺ وزوج فاطمة، ومن الخلفاء الراشدين، عُرف بالعلم والشجاعة.','Original concise biography for Zikr.','أبو تراب','الخلفاء الراشدون',305,true,'{"editorial":true}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,title_ar=excluded.title_ar,category=excluded.category,published=true,metadata=excluded.metadata;
insert into public.companions (id,name_ar,name_en,slug,bio_ar,bio_en,title_ar,category,order_num,published,metadata) values ('e08a95ca-050d-58fb-b709-685cd7b7bc8c','خالد بن الوليد','Khalid ibn al-Walid','khalid-ibn-walid','صحابي وقائد عسكري أسلم وأخلص، واشتهر بحسن التدبير في ميادين القتال.','Original concise biography for Zikr.','سيف الله المسلول','القادة',306,true,'{"editorial":true}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,title_ar=excluded.title_ar,category=excluded.category,published=true,metadata=excluded.metadata;
insert into public.companions (id,name_ar,name_en,slug,bio_ar,bio_en,title_ar,category,order_num,published,metadata) values ('7e0074fc-5b8b-593d-8f46-94d6d174d885','بلال بن رباح','Bilal ibn Rabah','bilal-ibn-rabah','صحابي جليل ثبت على التوحيد، وكان من أوائل المؤذنين.','Original concise biography for Zikr.','مؤذن رسول الله ﷺ','السابقون',307,true,'{"editorial":true}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,title_ar=excluded.title_ar,category=excluded.category,published=true,metadata=excluded.metadata;
insert into public.companions (id,name_ar,name_en,slug,bio_ar,bio_en,title_ar,category,order_num,published,metadata) values ('1924c656-fb33-5455-a830-70c2592708e3','بلال بن رباح','Bilal ibn Rabah','bilal','صحابي جليل ثبت على التوحيد، وكان من أوائل المؤذنين.','Original concise biography for Zikr.','مؤذن رسول الله ﷺ','السابقون',308,true,'{"editorial":true}') on conflict (slug) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,bio_ar=excluded.bio_ar,bio_en=excluded.bio_en,title_ar=excluded.title_ar,category=excluded.category,published=true,metadata=excluded.metadata;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('d6e91f6b-d443-57e3-9a5c-01a9ce04d848',(select id from public.companions where slug='abu-bakr' limit 1),'موقف الصديق في الهجرة','The Truthful Friend during the Hijrah','رافق أبو بكر النبي ﷺ في الهجرة، وكان ثباته في الغار مثالًا على الصحبة الصادقة وحسن التوكل. لم يكن التوكل تركًا للتخطيط؛ فقد أُعدت الراحلة واختير الطريق واستُعين بالخبرة، ثم اطمأن القلب إلى حفظ الله. الدرس العملي: الصحبة الصالحة تجمع المحبة والتخطيط والسكينة.','Original educational companion biography module prepared for Zikr.','faith',101) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('91d406fa-ef60-500f-b264-fb94fbfb8d47',(select id from public.companions where slug='abu-bakr' limit 1),'إنفاق الصديق وبذل المال','Abu Bakr’s Generosity','كان أبو بكر ينفق مما يملك في تحرير المستضعفين ونصرة الدعوة، فصار ماله وسيلة للرحمة لا للزينة. يعلّم الموقف أن قيمة المال فيما يحققه من حق وخير، مع ضرورة عدم إضاعة حقوق الأسرة. الدرس العملي: الإنفاق الواعي يحرر الإنسان من عبودية المال.','Original educational companion biography module prepared for Zikr.','generosity',102) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('ef715911-2d26-5a3d-b221-6186d2292f70',(select id from public.companions where slug='umar-ibn-khattab' limit 1),'عدل عمر ومراقبة المسؤولية','Umar and the Responsibility of Justice','ارتبطت سيرة عمر بمعنى محاسبة النفس والخوف من ظلم فرد في الرعية. تعرض القصة مفهومًا تربويًا: المسؤول لا ينتظر المديح، بل يسأل عن الضعيف ويضع أنظمة تمنع الاستغلال. الدرس العملي: العدل مؤسسات وسلوك يومي، وليس شعارًا فقط.','Original educational companion biography module prepared for Zikr.','justice',103) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('f56f1075-10ba-5192-a15e-686fb87f06f4',(select id from public.companions where slug='umar-ibn-khattab' limit 1),'إسلام عمر وقوة الحق','Umar’s Acceptance of Islam','كان إسلام عمر تحولًا في القوة الاجتماعية التي تخدم الدعوة، لكنه لم يكن إذنًا بالبطش؛ بل صار عمر يتعلم الانضباط والرحمة والوقوف عند حدود الله. الدرس العملي: القوة النافعة هي التي تُضبط بالحق.','Original educational companion biography module prepared for Zikr.','conversion',104) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('e0cea034-5db7-55c2-9a3e-1b1991399491',(select id from public.companions where slug='uthman-ibn-affan' limit 1),'حياء عثمان وبذله','Uthman’s Modesty and Giving','اشتهر عثمان بالحياء والإنفاق، ومن معاني سيرته أن الثراء يمكن أن يكون بابًا لخدمة المجتمع إذا صح القصد ولم يتحول إلى استعلاء. الدرس العملي: الحياء والإنفاق يرفعان قيمة النعمة.','Original educational companion biography module prepared for Zikr.','generosity',105) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('f934755f-e44b-5ab6-a453-05f724e48e09',(select id from public.companions where slug='uthman-ibn-affan' limit 1),'جمع الناس على المصحف','Uthman and the Written Mushaf','من أعظم أعمال عثمان جمع الناس على مصحف إمام دفعًا للاختلاف في القراءة، وهو عمل إداري علمي يحفظ النص ويجمع الأمة. يعرض هذا القسم المعنى التاريخي دون الدخول في تفاصيل لا تثبت. الدرس العملي: حفظ العلم يحتاج إلى توثيق ومؤسسات وتعاون.','Original educational companion biography module prepared for Zikr.','knowledge',106) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('8060bc32-c51a-5962-9572-5b5f0c1d43cd',(select id from public.companions where slug='ali-ibn-abi-talib' limit 1),'شجاعة علي وحكمته','Ali’s Courage and Wisdom','اجتمعت في علي الشجاعة والعلم والقرب من النبي ﷺ، وتظهر سيرته أن الشجاعة ليست اندفاعًا، بل ثبات مع معرفة العاقبة وحفظ حقوق الناس. الدرس العملي: الشجاعة الأخلاقية تحتاج علمًا وضبطًا للنفس.','Original educational companion biography module prepared for Zikr.','courage',107) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('015232cb-c05b-5633-9608-268608b70d92',(select id from public.companions where slug='khalid-ibn-walid' limit 1),'خالد بن الوليد وتعلم القيادة','Khalid ibn al-Walid and Leadership','تقدم سيرة خالد نموذجًا لقائد تعلم من التحول من خصومة الإسلام إلى خدمته، ثم جمع بين سرعة القرار وتنظيم الصفوف. وتبقى القيادة مسؤولية لا مجدًا شخصيًا. الدرس العملي: التغيير الصادق ممكن، والمهارة تصبح فضيلة حين تخدم الحق.','Original educational companion biography module prepared for Zikr.','leadership',108) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('ea4624c2-e381-5cc9-8e49-9bffd72add05',(select id from public.companions where slug='bilal-ibn-rabah' limit 1),'بلال والصبر على الأذى','Bilal and Steadfastness','واجه بلال التعذيب بسبب توحيده، فثبت على كلمة التوحيد حتى صار صوته رمزًا للأذان والكرامة. تذكر القصة أن مقاومة الظلم لا تعني ظلم الآخرين. الدرس العملي: الثبات يحفظ الكرامة، والرحمة تمنع تحول الألم إلى انتقام.','Original educational companion biography module prepared for Zikr.','steadfastness',109) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
insert into public.companion_stories (id,companion_id,title_ar,title_en,content_ar,content_en,story_type,order_num) values ('852d19b6-3dc7-5f14-998e-43019e61277d',(select id from public.companions where slug='bilal' limit 1),'بلال وخدمة المجتمع','Bilal’s Service to the Community','لم تكن منزلة بلال في صوته فقط؛ بل في أمانته وخدمته وصحبته للنبي ﷺ. يعرض هذا القسم قيمة العمل المتواضع الذي يبني الجماعة ويجمع القلوب. الدرس العملي: الخدمة الصادقة تصنع أثرًا يتجاوز الشهرة.','Original educational companion biography module prepared for Zikr.','service',110) on conflict (id) do update set companion_id=excluded.companion_id,title_ar=excluded.title_ar,title_en=excluded.title_en,content_ar=excluded.content_ar,content_en=excluded.content_en,story_type=excluded.story_type,order_num=excluded.order_num;
